    @Test
    void childrenAreOptionalAndShownOnTheReservation() throws Exception {
        JsonNode without = json.readTree(post("/reservations", RESERVATION_JSON).body());
        assertEquals(0, without.get("children").asInt());

        String withChildren = RESERVATION_JSON.replace("201", "202").replace("\"guests\": 2", "\"guests\": 2, \"children\": 1");
