        String tooMany = RESERVATION_JSON.replace("\"guests\": 2", "\"guests\": 2, \"children\": 2");
        assertEquals(422, post("/reservations", tooMany).statusCode());
        String negative = RESERVATION_JSON.replace("\"guests\": 2", "\"guests\": 2, \"children\": -1");
        assertEquals(400, post("/reservations", negative).statusCode());
    }

